'use strict';
const D=window.ANTENNA,C=window.AntennaCore,$=id=>document.getElementById(id);
const maps={};for(const k of ['groups','categories','members','songs','topics'])maps[k]=new Map(D.taxonomy[k].map(x=>[x.id,x]));
const writers=new Map(D.authors.map(x=>[x.id,x]));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=(ids,k)=>ids.map(id=>maps[k].get(id)?.name||id);
const rows=D.articles.map(a=>({...a,search:C.norm([a.title,writers.get(a.author_id)?.name,...['groups','members','songs','categories','topics'].flatMap(k=>(a[{groups:'group_ids',members:'member_ids',songs:'song_ids',categories:'category_ids',topics:'topic_ids'}[k]]||[]).flatMap(id=>{const x=maps[k].get(id);return x?[x.name,...(x.aliases||[])]:[]})),...(a.keywords||[])].join(' '))}));
function search(items,filters){return C.filter(items,filters,D.taxonomy.groups)}
let shown=30,selected=[],author=window.PRESET_AUTHOR||'',randomOrder=C.shuffle(rows),writerOrder=C.shuffle(D.authors);
function article(a){const w=writers.get(a.author_id),groups=names(a.group_ids,'groups'),categories=names(a.category_ids,'categories');return `<article class="article"><div class="article-kicker"><span class="article-groups">${escape((groups.length?groups:categories).join(' / '))}</span><time datetime="${escape(a.published_at)}">${escape(C.day(a.published_at).replace(/-/g,'.'))}</time></div><h3><a href="${escape(a.url)}" rel="external">${escape(a.title)}</a></h3><div class="meta"><a href="authors/${escape(a.author_id)}.html">${escape(w?.name||a.author_id)}</a><span>${escape(w?.platform||'')}</span></div><div class="tags">${names(a.topic_ids,'topics').map(t=>`<span class="tag">${escape(t)}</span>`).join('')}</div></article>`}
function options(id,list,first){const prev=$(id).value;$(id).replaceChildren(new Option(first,''),...list.map(x=>new Option(x.name,x.id)));if(list.some(x=>x.id===prev))$(id).value=prev}
function groupOptions(){const cat=$('category').value,q=C.norm($('group-query').value);const attached=new Set(rows.filter(a=>a.category_ids.includes(cat)).flatMap(a=>a.group_ids));options('group',D.taxonomy.groups.filter(g=>(!cat||g.category_id===cat||attached.has(g.id))&&(!q||[g.name,...g.aliases].some(n=>C.norm(n).includes(q)))),'すべてのグループ・ソロ')}
function current(){return {q:$('query').value,category:$('category').value,group:$('group').value,topic:$('topic').value,era:$('era').value,author}}
function renderArticles(){const f=current();let found=search($('sort').value==='random'?randomOrder:rows,f);found=[...found];if($('sort').value==='old')found.sort((a,b)=>a.published_at.localeCompare(b.published_at));else if($('sort').value!=='random')found.sort((a,b)=>b.published_at.localeCompare(a.published_at));selected=$('sort').value==='balanced'?C.balanced(found):found;
$('count').textContent=`${found.length.toLocaleString()} 件`;$('articles').innerHTML=selected.length?selected.slice(0,shown).map(article).join(''):'<div class="empty"><strong>この条件では、まだ見つかりません。</strong><p>検索語を短くするか、分類・年代をひとつ外して探してみてください。</p></div>';$('more').hidden=shown>=selected.length;$('active-author').textContent=author?`${writers.get(author)?.name||author} の記事`:'';
const picks=D.pickups.filter(p=>found.some(a=>a.url===p.url));$('pickups').hidden=!picks.length||Boolean(f.q||author||f.topic||f.era);$('pickup-list').innerHTML=picks.map(p=>`<div class="pickup-entry">${article(found.find(a=>a.url===p.url))}<p class="pickup-note">${escape(p.note)}</p></div>`).join('');
const params=new URLSearchParams();for(const [k,v] of Object.entries(f))if(v)params.set(k,v);if($('sort').value!=='balanced')params.set('sort',$('sort').value);history.replaceState(null,'',location.pathname+(params.size?'?'+params:''));}
function renderWriters(){const f=current();const ids=new Set(search(rows,{...f,author:''}).map(a=>a.author_id));const list=writerOrder.filter(w=>ids.has(w.id));$('count').textContent=`${list.length} 人`;$('articles').innerHTML=list.length?'<div class="writer-grid">'+list.slice(0,shown).map(w=>`<article class="writer"><p class="writer-platform">${escape(w.platform)}</p><h2><a href="authors/${escape(w.id)}.html">${escape(w.name)} <span aria-hidden="true">→</span></a></h2><p>${w.count} 記事を収録</p><p>${escape(w.groups.join(' / '))}</p><a class="writer-source" href="${escape(w.url)}" rel="external">元のブログ・noteへ ↗</a></article>`).join('')+'</div>':'<div class="empty"><strong>この条件の書き手は見つかりません。</strong><p>検索語や絞り込み条件を変えてみてください。</p></div>';$('more').hidden=shown>=list.length;
const params=new URLSearchParams();for(const [k,v] of Object.entries(f))if(v)params.set(k,v);history.replaceState(null,'',location.pathname+(params.size?'?'+params:''));}
const isWriters=window.VIEW==='writers';
function clearDraw(){ $('draw-result').replaceChildren();$('draw-panel').hidden=true; }
function render(){isWriters?renderWriters():renderArticles();renderConditions();window.AntennaAnalytics?.update({...current(),sort:$('sort').value},parseInt($('count').textContent.replace(/,/g,''),10)||0)}
function renderConditions(){const f=current(),labels={category:'categories',group:'groups',topic:'topics'};const chips=[];for(const key of ['q','category','group','topic','era']){if(!f[key])continue;const label=key==='q'?`検索：${f[key]}`:key==='era'?f[key]+'年代':maps[labels[key]].get(f[key])?.name||f[key];chips.push(`<button type="button" data-clear="${key}" aria-label="${escape(label)}の条件を解除">${escape(label)} <span aria-hidden="true">×</span></button>`)}$('active-filters').innerHTML=chips.join('');const n=['category','group','topic','era'].filter(k=>f[k]).length;$('filter-status').textContent=n?`${n}条件 選択中`:'';for(const link of document.querySelectorAll('[data-theme]'))link.setAttribute('aria-current',String(link.dataset.theme===f.topic));}
options('category',D.taxonomy.categories,'すべての大分類');options('topic',D.taxonomy.topics,'すべてのテーマ');groupOptions();options('era',[...new Set(rows.map(a=>Math.floor(Number(C.day(a.published_at).slice(0,4))/10)*10))].sort((a,b)=>b-a).map(n=>({id:String(n),name:n+'年代'})),'すべての年代');
const params=new URLSearchParams(location.search);for(const [key,id] of [['q','query'],['category','category'],['topic','topic'],['era','era'],['sort','sort']])if(params.has(key))$(id).value=params.get(key);groupOptions();if(params.has('group'))$('group').value=params.get('group');if(params.get('author')&&writers.has(params.get('author')))author=params.get('author');
$('stats').innerHTML=`<span class="stat"><strong>${D.articles.length.toLocaleString()}</strong>記事</span><span class="stat"><strong>${D.authors.length.toLocaleString()}</strong>人の書き手</span>`;
document.body.dataset.view=isWriters?'writers':author?'author':'articles';
document.querySelector(`[data-nav="${isWriters?'writers':'articles'}"]`).setAttribute('aria-current','page');
if(isWriters)$('intro-description').textContent='ひとりの視点から、次の文章へ。気になる書き手を見つけてください。';
else if(author){const w=writers.get(author);$('intro-description').textContent=`${w?.name||author} が書いた、アイドルの考察・批評・感想。`;}
const themeCounts=new Map(D.taxonomy.topics.map(t=>[t.id,rows.filter(a=>a.topic_ids.includes(t.id)).length]));
$('theme-links').innerHTML=[{id:'',name:'すべての視点'},...D.taxonomy.topics].map(t=>`<a class="theme-link" data-theme="${escape(t.id)}" href="${isWriters?'writers':'index'}.html${t.id?'?topic='+encodeURIComponent(t.id):''}">${escape(t.name)}<span>${t.id?themeCounts.get(t.id):rows.length}</span></a>`).join('');
const desktop=matchMedia('(min-width:861px)');function indexState(){ $('topic-index').open=desktop.matches; }indexState();desktop.addEventListener('change',indexState);
if(['category','group','topic','era'].some(k=>params.get(k)))$('filter-details').open=true;
$('theme-links').addEventListener('click',e=>{const link=e.target.closest('[data-theme]');if(!link||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();$('topic').value=link.dataset.theme;shown=30;clearDraw();render();$('results').scrollIntoView({block:'start'});$('results').focus({preventScroll:true});});
$('active-filters').addEventListener('click',e=>{const button=e.target.closest('[data-clear]');if(!button)return;const key=button.dataset.clear;$(key==='q'?'query':key).value='';if(key==='category')groupOptions();shown=30;clearDraw();render();$('reset').focus({preventScroll:true});});
$('search-form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(timer);shown=30;clearDraw();render();window.AntennaAnalytics?.flushSearch();$('results').scrollIntoView({block:'start'});$('results').focus({preventScroll:true});});
$('close-draw').onclick=()=>{clearDraw();$('random').focus({preventScroll:true});};
for(const id of ['category','group','topic','era','sort'])$(id).addEventListener('change',()=>{if(id==='category')groupOptions();if(id==='sort')randomOrder=C.shuffle(rows);shown=30;clearDraw();render()});
let timer;for(const id of ['query','group-query'])$(id).addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(id==='group-query')groupOptions();shown=30;clearDraw();render()},100)});
$('reset').onclick=()=>{for(const id of ['query','category','group','group-query','topic','era'])$(id).value='';groupOptions();$('sort').value='balanced';author=window.PRESET_AUTHOR||'';shown=30;clearDraw();render()};
$('more').onclick=()=>{shown+=30;render();window.AntennaAnalytics?.track('more_results',{shown_count:shown})};
for(const old of [false,true])$(old?'old-random':'random').onclick=()=>{const cutoff=new Date(Date.now()-30*86400000).toISOString();const pool=search(rows,current()).filter(a=>!old||a.published_at<cutoff);const a=C.draw(pool);$('draw-panel').hidden=false;$('draw-result').innerHTML=a?article(a):'<p class="empty">この条件で抽選できる記事はありません。</p>';$('draw-heading').textContent=old?'時を越えて、めぐり合った一篇':'めぐり合った一篇';$('draw-panel').setAttribute('tabindex','-1');$('draw-panel').scrollIntoView({block:'start'});$('draw-panel').focus({preventScroll:true});window.AntennaAnalytics?.track('random_draw',{draw_type:old?'past':'all',has_result:String(Boolean(a)),article_id:a?.id||''});window.AntennaAnalytics?.observe()};
if(isWriters){$('discovery').hidden=true;$('sort').parentElement.hidden=true;$('results-heading').textContent='書き手を探す';$('results-eyebrow').textContent='THE WRITER INDEX';$('more').textContent='さらに30人を見る';const b=document.createElement('button');b.className='quiet';b.textContent='書き手を並べ直す';b.onclick=()=>{writerOrder=C.shuffle(D.authors);render();window.AntennaAnalytics?.track('writer_shuffle')};$('active-author').append(b)}
render();
